import matter from 'gray-matter';
import { marked } from 'marked';

export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[];
}

export interface ParsedMarkdown {
  frontmatter: Frontmatter;
  contentHtml: string;
}

function toDateString(value: unknown): string | undefined {
  if (typeof value === 'string' && value.length > 0) return value;
  if (value instanceof Date && !Number.isNaN(value.getTime())) return value.toISOString();
  return undefined;
}

function toTags(value: unknown): string[] | undefined {
  if (Array.isArray(value)) {
    return value.map((tag) => String(tag)).filter((tag) => tag.length > 0);
  }
  if (typeof value === 'string' && value.length > 0) {
    return value
      .split(',')
      .map((tag) => tag.trim())
      .filter((tag) => tag.length > 0);
  }
  return undefined;
}

export function parseMarkdown(raw: string): ParsedMarkdown {
  const { data, content } = matter(raw);
  const frontmatter: Frontmatter = {
    title: typeof data.title === 'string' ? data.title : undefined,
    date: toDateString(data.date),
    tags: toTags(data.tags),
  };
  const contentHtml = marked.parse(content.trim());
  return { frontmatter, contentHtml };
}

import { readFileSync } from 'fs';
import { basename, extname } from 'path';
import { parseMarkdown } from './markdown';

export interface Page {
  slug: string;
  title: string;
  date: string;
  tags: string[];
  contentHtml: string;
}

export function pageFromFile(filePath: string): Page {
  const raw = readFileSync(filePath, 'utf8');
  const parsed = parseMarkdown(raw);
  const slug = basename(filePath, extname(filePath));
  return {
    slug,
    title: parsed.frontmatter.title ?? slug,
    date: parsed.frontmatter.date ?? '',
    tags: parsed.frontmatter.tags ?? [],
    contentHtml: parsed.contentHtml,
  };
}

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function tagSpans(tags: string[]): string {
  return tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ');
}

function dateElement(date: string): string {
  if (!date) return '';
  return `<time datetime="${escapeHtml(date)}">${escapeHtml(date)}</time>`;
}

import { Page } from './page';
import { escapeHtml, tagSpans, dateElement } from './html';

export function pageHtml(page: Page): string {
  const tags = tagSpans(page.tags);
  const date = dateElement(page.date);
  const metaLine = [date, tags].filter((part) => part.length > 0).join(' ');
  return [
    '<!DOCTYPE html>',
    '<html lang="en">',
    '<head>',
    '  <meta charset="utf-8">',
    `  <meta name="viewport" content="width=device-width, initial-scale=1">`,
    `  <title>${escapeHtml(page.title)}</title>`,
    '</head>',
    '<body>',
    '  <header>',
    `    <h1>${escapeHtml(page.title)}</h1>`,
    metaLine ? `    <p class="meta">${metaLine}</p>` : '',
    '    <p><a href="index.html">&larr; Home</a></p>',
    '  </header>',
    '  <main>',
    page.contentHtml,
    '  </main>',
    '</body>',
    '</html>',
    '',
  ]
    .filter((line) => line !== undefined)
    .join('\n');
}

export function indexHtml(pages: Page[]): string {
  const items = pages
    .map((page) => {
      const date = dateElement(page.date);
      const tags = tagSpans(page.tags);
      const meta = [date, tags].filter((part) => part.length > 0).join(' ');
      return [
        '    <li>',
        `      <a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.title)}</a>`,
        meta ? `      <span class="meta">${meta}</span>` : '',
        '    </li>',
      ]
        .filter((line) => line !== '')
        .join('\n');
    })
    .join('\n');

  return [
    '<!DOCTYPE html>',
    '<html lang="en">',
    '<head>',
    '  <meta charset="utf-8">',
    '  <meta name="viewport" content="width=device-width, initial-scale=1">',
    '  <title>Home</title>',
    '</head>',
    '<body>',
    '  <header>',
    '    <h1>Home</h1>',
    '  </header>',
    '  <main>',
    pages.length > 0 ? '    <ul class="pages">\n' + items + '\n    </ul>' : '    <p>No pages yet.</p>',
    '  </main>',
    '</body>',
    '</html>',
    '',
  ].join('\n');
}

import { mkdirSync, readdirSync, writeFileSync } from 'fs';
import { join } from 'path';
import { Page, pageFromFile } from './page';
import { indexHtml, pageHtml } from './templates';

export function listMarkdownFiles(dir: string): string[] {
  const files: string[] = [];
  const entries = readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...listMarkdownFiles(fullPath));
    } else if (entry.isFile() && entry.name.endsWith('.md')) {
      files.push(fullPath);
    }
  }
  return files;
}

export function buildSite(contentDir: string, outputDir: string): Page[] {
  const files = listMarkdownFiles(contentDir);
  const pages = files.map(pageFromFile);
  pages.sort((a, b) => b.date.localeCompare(a.date));

  mkdirSync(outputDir, { recursive: true });
  for (const page of pages) {
    writeFileSync(join(outputDir, `${page.slug}.html`), pageHtml(page), 'utf8');
  }
  writeFileSync(join(outputDir, 'index.html'), indexHtml(pages), 'utf8');
  return pages;
}

import { buildSite } from './build';
import { Page } from './page';

export interface CliOptions {
  content: string;
  output: string;
}

export interface ParsedCli {
  command: string;
  options: CliOptions;
}

const DEFAULT_CONTENT = './content';
const DEFAULT_OUTPUT = './dist';

function usage(): string {
  return [
    'Usage: ssg build [options]',
    '',
    'Options:',
    '  --content <dir>   Markdown source directory (default: ./content)',
    '  --output <dir>    Output directory (default: ./dist)',
    '  -h, --help        Show this help',
  ].join('\n');
}

function parseFlagValue(argv: string[], flag: string, index: number): string | null {
  const arg = argv[index];
  if (arg === flag) {
    const value = argv[index + 1];
    return value !== undefined ? value : null;
  }
  if (arg.startsWith(`${flag}=`)) {
    return arg.slice(flag.length + 1);
  }
  return null;
}

export function parseArgs(argv: string[]): ParsedCli | null {
  const args = argv.slice();
  const command = args.shift();
  if (command === undefined || command === '-h' || command === '--help') return null;
  if (command !== 'build') return null;

  const options: CliOptions = { content: DEFAULT_CONTENT, output: DEFAULT_OUTPUT };
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '-h' || arg === '--help') return null;
    const contentValue = parseFlagValue(args, '--content', i);
    if (contentValue !== null) {
      options.content = contentValue;
      if (args[i] === '--content') i++;
      continue;
    }
    const outputValue = parseFlagValue(args, '--output', i);
    if (outputValue !== null) {
      options.output = outputValue;
      if (args[i] === '--output') i++;
      continue;
    }
    return null;
  }
  return { command, options };
}

export function run(argv: string[]): number {
  const parsed = parseArgs(argv);
  if (parsed === null) {
    process.stdout.write(usage() + '\n');
    return 1;
  }

  try {
    const pages: Page[] = buildSite(parsed.options.content, parsed.options.output);
    process.stdout.write(`Built ${pages.length} page(s) into ${parsed.options.output}\n`);
    return 0;
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    process.stderr.write(`Error: ${message}\n`);
    return 1;
  }
}

function main(): void {
  process.exitCode = run(process.argv.slice(2));
}

if (require.main === module) {
  main();
}

export { buildSite, listMarkdownFiles } from './build';
export { Page, pageFromFile } from './page';
export { parseMarkdown, ParsedMarkdown, Frontmatter } from './markdown';
export { pageHtml, indexHtml } from './templates';

import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';

export interface Fixture {
  root: string;
  contentDir: string;
  outputDir: string;
}

export function createFixture(files: Record<string, string>): Fixture {
  const root = mkdtempSync(join(tmpdir(), 'ssg-'));
  const contentDir = join(root, 'content');
  const outputDir = join(root, 'dist');
  mkdirSync(contentDir, { recursive: true });
  for (const [relativePath, contents] of Object.entries(files)) {
    const fullPath = join(contentDir, relativePath);
    mkdirSync(join(fullPath, '..'), { recursive: true });
    writeFileSync(fullPath, contents, 'utf8');
  }
  return { root, contentDir, outputDir };
}

export function cleanupFixture(fixture: Fixture): void {
  rmSync(fixture.root, { recursive: true, force: true });
}

import { parseMarkdown } from '../src/markdown';

describe('parseMarkdown', () => {
  it('converts markdown body to HTML', () => {
    const result = parseMarkdown('---\ntitle: Hello\n---\n\n# Heading\n\nSome **bold** text.');
    expect(result.contentHtml).toContain('<h1>Heading</h1>');
    expect(result.contentHtml).toContain('<strong>bold</strong>');
  });

  it('extracts title, date and tags from frontmatter', () => {
    const result = parseMarkdown(
      '---\ntitle: My Post\ndate: 2024-05-01\ntags: [typescript, node]\n---\n\nBody.'
    );
    expect(result.frontmatter.title).toBe('My Post');
    expect(result.frontmatter.tags).toEqual(['typescript', 'node']);
    expect(result.frontmatter.date).not.toBeUndefined();
  });

  it('treats a YAML date as a valid date string', () => {
    const result = parseMarkdown('---\ndate: 2024-05-01\n---\n\nBody.');
    expect(result.frontmatter.date).toBeDefined();
  });

  it('parses comma-separated tags as an array', () => {
    const result = parseMarkdown('---\ntags: one, two\n---\n\nBody.');
    expect(result.frontmatter.tags).toEqual(['one', 'two']);
  });

  it('returns empty defaults when frontmatter is missing', () => {
    const result = parseMarkdown('# Just a heading');
    expect(result.frontmatter.title).toBeUndefined();
    expect(result.frontmatter.date).toBeUndefined();
    expect(result.frontmatter.tags).toBeUndefined();
    expect(result.contentHtml).toContain('<h1>Just a heading</h1>');
  });
});

import { existsSync, readFileSync } from 'fs';
import { join } from 'path';
import { buildSite, listMarkdownFiles } from '../src/build';
import { createFixture, cleanupFixture, Fixture } from './helpers';

describe('buildSite', () => {
  let fixture: Fixture;

  afterEach(() => {
    cleanupFixture(fixture);
  });

  it('generates an HTML file for every markdown page', () => {
    fixture = createFixture({
      'about.md': '---\ntitle: About\ntags: meta\n---\n\n## About us',
      'post.md': '---\ntitle: First Post\ndate: 2024-01-01\n---\n\nHello **world**.',
    });

    const pages = buildSite(fixture.contentDir, fixture.outputDir);

    expect(pages).toHaveLength(2);
    expect(existsSync(join(fixture.outputDir, 'about.html'))).toBe(true);
    expect(existsSync(join(fixture.outputDir, 'post.html'))).toBe(true);
  });

  it('renders markdown content into each page HTML', () => {
    fixture = createFixture({
      'post.md': '---\ntitle: First Post\ntags: [a, b]\n---\n\nHello **world**.',
    });

    buildSite(fixture.contentDir, fixture.outputDir);

    const pageHtml = readFileSync(join(fixture.outputDir, 'post.html'), 'utf8');
    expect(pageHtml).toContain('<title>First Post</title>');
    expect(pageHtml).toContain('<strong>world</strong>');
    expect(pageHtml).toContain('class="tag">a</span>');
  });

  it('generates an index.html listing all pages', () => {
    fixture = createFixture({
      'one.md': '---\ntitle: One\ndate: 2024-01-01\n---\n\nOne.',
      'two.md': '---\ntitle: Two\ndate: 2024-02-01\n---\n\nTwo.',
    });

    buildSite(fixture.contentDir, fixture.outputDir);

    const index = readFileSync(join(fixture.outputDir, 'index.html'), 'utf8');
    expect(index).toContain('href="one.html"');
    expect(index).toContain('href="two.html"');
    expect(index).toContain('>One</a>');
    expect(index).toContain('>Two</a>');
  });

  it('sorts pages by date descending on the index', () => {
    fixture = createFixture({
      'one.md': '---\ntitle: One\ndate: 2024-01-01\n---\n\nOne.',
      'two.md': '---\ntitle: Two\ndate: 2024-02-01\n---\n\nTwo.',
      'three.md': '---\ntitle: Three\ndate: 2024-03-01\n---\n\nThree.',
    });

    const pages = buildSite(fixture.contentDir, fixture.outputDir);
    expect(pages.map((p) => p.title)).toEqual(['Three', 'Two', 'One']);
  });

  it('recursively discovers markdown files in subdirectories', () => {
    fixture = createFixture({
      'nested/inner.md': '---\ntitle: Inner\n---\n\nInner content.',
    });

    const files = listMarkdownFiles(fixture.contentDir);
    expect(files).toHaveLength(1);

    buildSite(fixture.contentDir, fixture.outputDir);
    expect(existsSync(join(fixture.outputDir, 'inner.html'))).toBe(true);
  });

  it('creates the output directory when it does not exist', () => {
    fixture = createFixture({
      'post.md': '# No frontmatter',
    });

    buildSite(fixture.contentDir, fixture.outputDir);
    expect(existsSync(join(fixture.outputDir, 'index.html'))).toBe(true);
    expect(existsSync(join(fixture.outputDir, 'post.html'))).toBe(true);
  });

  it('falls back to the filename as the page title', () => {
    fixture = createFixture({
      'untitled.md': 'Just body text without frontmatter.',
    });

    const pages = buildSite(fixture.contentDir, fixture.outputDir);
    expect(pages[0].title).toBe('untitled');
  });
});

import { execSync } from 'child_process';
import { existsSync, readFileSync } from 'fs';
import { join } from 'path';
import { parseArgs, run } from '../src/cli';
import { createFixture, cleanupFixture, Fixture } from './helpers';

describe('parseArgs', () => {
  it('uses defaults for content and output', () => {
    const parsed = parseArgs(['build']);
    expect(parsed).toEqual({ command: 'build', options: { content: './content', output: './dist' } });
  });

  it('accepts --content and --output flags', () => {
    const parsed = parseArgs(['build', '--content', 'src/md', '--output', 'public']);
    expect(parsed).toEqual({ command: 'build', options: { content: 'src/md', output: 'public' } });
  });

  it('accepts --content=dir syntax', () => {
    const parsed = parseArgs(['build', '--content=posts', '--output=out']);
    expect(parsed).toEqual({ command: 'build', options: { content: 'posts', output: 'out' } });
  });

  it('rejects unknown subcommands', () => {
    expect(parseArgs(['serve'])).toBeNull();
  });

  it('rejects unknown flags', () => {
    expect(parseArgs(['build', '--bogus'])).toBeNull();
  });
});

describe('run', () => {
  let fixture: Fixture;

  afterEach(() => {
    cleanupFixture(fixture);
  });

  it('builds the site and returns exit code 0', () => {
    fixture = createFixture({
      'hello.md': '---\ntitle: Hello\n---\n\nHi there.',
    });

    const code = run(['build', '--content', fixture.contentDir, '--output', fixture.outputDir]);
    expect(code).toBe(0);
    expect(existsSync(join(fixture.outputDir, 'hello.html'))).toBe(true);
    expect(existsSync(join(fixture.outputDir, 'index.html'))).toBe(true);
  });

  it('returns exit code 1 and reports an error for a missing content dir', () => {
    fixture = createFixture({});

    const code = run(['build', '--content', join(fixture.root, 'missing'), '--output', fixture.outputDir]);
    expect(code).toBe(1);
  });

  it('returns exit code 1 for invalid arguments', () => {
    fixture = createFixture({});
    expect(run(['serve'])).toBe(1);
  });
});

describe('compiled CLI binary', () => {
  let fixture: Fixture;

  beforeAll(() => {
    execSync('npx tsc -p tsconfig.json', { cwd: process.cwd(), stdio: 'pipe' });
  });

  afterEach(() => {
    cleanupFixture(fixture);
  });

  it('supports `ssg build` end to end', () => {
    fixture = createFixture({
      'post.md': '---\ntitle: Post\ndate: 2024-01-01\n---\n\nBody.',
    });

    const cli = join(process.cwd(), 'dist', 'cli.js');
    const output = execSync(`node ${cli} build --content ${fixture.contentDir} --output ${fixture.outputDir}`, {
      encoding: 'utf8',
    });

    expect(output).toContain('Built 1 page(s)');
    expect(existsSync(join(fixture.outputDir, 'post.html'))).toBe(true);
    const page = readFileSync(join(fixture.outputDir, 'post.html'), 'utf8');
    expect(page).toContain('<title>Post</title>');
  });

  it('fails with a non-zero exit when the content dir is missing', () => {
    fixture = createFixture({});

    let failed = false;
    try {
      execSync(
        `node ${join(process.cwd(), 'dist', 'cli.js')} build --content ${join(fixture.root, 'nope')} --output ${fixture.outputDir}`,
        { stdio: 'pipe' }
      );
    } catch (err) {
      failed = (err as { status?: number }).status !== 0;
    }
    expect(failed).toBe(true);
  });
});

